const monedas = $input.all();
if (!monedas || monedas.length === 0) throw new Error('❌ No se obtuvieron monedas');
const moneda = monedas.find(m => m.json.name === 'USD');
if (!moneda) throw new Error('❌ USD no encontrado');
console.log(`✅ Moneda: ${moneda.json.name} (${moneda.json.symbol})`);
return { json: { currency_id: moneda.json.id, currency_name: moneda.json.name, currency_symbol: moneda.json.symbol } };

const inputData = $input.first().json;
const moneda = $('Seleccionar Moneda').first().json;
let html = typeof inputData === 'string' ? inputData : inputData.body || inputData.data;
if (!html) throw new Error('❌ No se pudo obtener HTML');
let venta = null, compra = null, fecha = null;
const regexBilletes = /<div[^>]*id="billetes"[^>]*>([\s\S]*?)<\/div>\s*<div[^>]*class="tab-pane/i;
const matchBilletes = html.match(regexBilletes);
if (matchBilletes) {
  const seccionBilletes = matchBilletes[1];
  const regexFecha = /<th[^>]*class="fechaCot"[^>]*>([^<]+)<\/th>/i;
  const matchFecha = seccionBilletes.match(regexFecha);
  if (matchFecha) fecha = matchFecha[1].trim();
  const regexDolar = /<td[^>]*class="tit"[^>]*>Dolar U\.S\.A<\/td>\s*<td>([^<]+)<\/td>\s*<td>([^<]+)<\/td>/i;
  const matchDolar = seccionBilletes.match(regexDolar);
  if (matchDolar) {
    compra = parseFloat(matchDolar[1].trim().replace('.', '').replace(',', '.'));
    venta = parseFloat(matchDolar[2].trim().replace('.', '').replace(',', '.'));
  }
}
if (!venta) {
  const regexSimple = /Dolar\s+U\.S\.A[^\d]*([0-9]{1,5},[0-9]{2})[^\d]*([0-9]{1,5},[0-9]{2})/i;
  const matchSimple = html.match(regexSimple);
  if (matchSimple) {
    compra = parseFloat(matchSimple[1].replace('.', '').replace(',', '.'));
    venta = parseFloat(matchSimple[2].replace('.', '').replace(',', '.'));
  }
}
if (!venta || isNaN(venta) || venta < 100 || venta > 3000) throw new Error(`❌ No se extrajo tasa válida: ${venta}`);
let fechaISO = new Date().toISOString().split('T')[0];
if (fecha) {
  try {
    const [dia, mes, anio] = fecha.split('/');
    fechaISO = `${anio}-${mes.padStart(2, '0')}-${dia.padStart(2, '0')}`;
  } catch (e) {}
}
console.log(`\n💱 Tasa BNA: ${moneda.currency_symbol}${venta.toFixed(2)} | ${fechaISO}\n`);
return { json: { compra, venta, fecha: fechaISO, fecha_bna: fecha, currency_id: moneda.currency_id, currency_name: moneda.currency_name, currency_symbol: moneda.currency_symbol } };

const empresas = $input.all();
const principales = empresas.filter(e => !e.json.parent_id || e.json.parent_id === false || (Array.isArray(e.json.parent_id) && !e.json.parent_id[0]));
console.log(`🏢 Empresas principales: ${principales.length}`);
if (principales.length === 0) throw new Error('❌ No se encontraron empresas principales');
principales.forEach((e, i) => console.log(`   ${i + 1}. ${e.json.name} (ID: ${e.json.id}`));
return principales;

const cotizacion = $('Procesar Cotización BNA').first().json;
const empresas = $input.all();
console.log(`\n⚙️ Preparando ${empresas.length} empresas...\n`);
return empresas.map((empresa, index) => {
  console.log(`   📌 [${index + 1}/${empresas.length}] ${empresa.json.name}`);
  return {
    json: {
      company_id: empresa.json.id,
      company_name: empresa.json.name,
      currency_id: cotizacion.currency_id,
      fecha: cotizacion.fecha,
      inverse_company_rate: cotizacion.venta
    }
  };
});

const busqueda = $input.first().json;
const empresa = $('🔁 Procesar Cada Empresa').first().json;

const existe = busqueda && busqueda.id ? true : false;
const accion = existe ? 'ACTUALIZAR' : 'CREAR';
const icon = existe ? '🔄' : '✨';

console.log(`${icon} ${empresa.company_name}: ${accion} (Rate ID: ${busqueda?.id || 'N/A'})`);

return {
  json: {
    id: busqueda?.id || null,
    company_id: empresa.company_id,
    company_name: empresa.company_name,
    currency_id: empresa.currency_id,
    fecha: empresa.fecha,
    inverse_company_rate: empresa.inverse_company_rate,
    existe: existe,
    accion: accion
  }
};

// Este nodo recolecta los resultados de actualización
const inputItem = $input.first().json;
const preservados = $('Preservar Datos').all();
const itemIndex = $itemIndex;

const preservado = preservados[itemIndex].json;

console.log(`✅ Actualizado: ${preservado.company_name} (Rate ID: ${inputItem.id})`);

return {
  json: {
    company_id: inputItem.company_id || preservado.company_id,
    company_name: preservado.company_name,
    rate_id: inputItem.id,
    value: inputItem.inverse_company_rate,
    fecha: preservado.fecha,
    action: 'updated'
  }
};

// Este nodo recolecta los resultados de creación
const inputItem = $input.first().json;
const preservados = $('Preservar Datos').all();
const itemIndex = $itemIndex;

const preservado = preservados[itemIndex].json;

console.log(`✨ Creado: ${preservado.company_name} (Rate ID: ${inputItem.id})`);

return {
  json: {
    company_id: inputItem.company_id,
    company_name: preservado.company_name,
    rate_id: inputItem.id,
    value: inputItem.inverse_company_rate,
    fecha: inputItem.name,
    action: 'created'
  }
};

// Esperar a que todos los procesos terminen y generar resumen
const cotizacion = $('Procesar Cotización BNA').first().json;
const agregado = $input.first().json;

const resultados = agregado.resultados || [];

if (resultados.length === 0) {
  throw new Error('❌ No se procesó ninguna empresa. Verificar logs anteriores.');
}

const creadas = resultados.filter(r => r.action === 'created').length;
const actualizadas = resultados.filter(r => r.action === 'updated').length;

console.log('\n' + '='.repeat(70));
console.log('✅ ACTUALIZACIÓN USD BNA COMPLETADA');
console.log('='.repeat(70));
console.log(`💱 ${cotizacion.currency_name}: ${cotizacion.currency_symbol}${cotizacion.venta.toFixed(2)}`);
console.log(`📅 ${cotizacion.fecha}`);
console.log(`📊 Creadas: ${creadas} | Actualizadas: ${actualizadas} | Total: ${resultados.length}`);
resultados.forEach((r, idx) => {
  const icon = r.action === 'created' ? '✨' : '🔄';
  console.log(`   ${idx + 1}. ${icon} ${r.company_name}: ${cotizacion.currency_symbol}${r.value}`);
});
console.log('='.repeat(70) + '\n');

return {
  json: {
    status: 'success',
    timestamp: new Date().toISOString(),
    timestamp_ar: new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' }),
    ejecutado_por: 'EconovoOdoo',
    moneda: { 
      codigo: cotizacion.currency_name, 
      id: cotizacion.currency_id, 
      simbolo: cotizacion.currency_symbol 
    },
    cotizacion: { 
      venta: cotizacion.venta, 
      compra: cotizacion.compra, 
      fecha: cotizacion.fecha 
    },
    resultado: { 
      total: resultados.length, 
      creadas: creadas, 
      actualizadas: actualizadas 
    },
    detalle: resultados
  }
};
